using EduManageLms.Api.Infrastructure; using MongoDB.Bson; using MongoDB.Driver;
namespace EduManageLms.Api.Application;
public sealed class DashboardService(MongoContext db,IStudentAnalyticsService analytics):IDashboardService{
 public async Task<DashboardDto> AdminAsync(CancellationToken ct){var students=await db.Students.CountDocumentsAsync(x=>!x.IsDeleted,cancellationToken:ct);var lecturers=await db.Lecturers.CountDocumentsAsync(x=>!x.IsDeleted,cancellationToken:ct);var courses=await db.Courses.CountDocumentsAsync(x=>!x.IsDeleted,cancellationToken:ct);var sections=await db.ClassSections.CountDocumentsAsync(x=>!x.IsDeleted,cancellationToken:ct);return Build([new("Sinh viên",students,"school","+8 trong học kỳ","primary"),new("Giảng viên",lecturers,"badge","Đang hoạt động","success"),new("Môn học",courses,"menu_book","Có cấu trúc điểm","warning"),new("Lớp học phần",sections,"class","10 lớp đang mở","primary")]);}
 public async Task<DashboardDto> LecturerAsync(string code,CancellationToken ct){var sections=await db.ClassSections.Find(x=>x.LecturerCode==code&&!x.IsDeleted).ToListAsync(ct);return Build([new("Lớp phụ trách",sections.Count,"class","Học kỳ hiện tại","primary"),new("Tổng sinh viên",sections.Sum(x=>x.Students.Count),"groups","Trong các lớp","success"),new("Chưa công bố",sections.Count(x=>x.GradeStatus!="Published"),"pending_actions","Cần hoàn tất","warning"),new("Đã công bố",sections.Count(x=>x.GradeStatus=="Published"),"verified","Bảng điểm","success")]);}
 public async Task<DashboardDto> StudentAsync(string code,CancellationToken ct){var gpa=await analytics.GetCumulativeGpaAsync(code,ct);var grades=await analytics.GetGradesAsync(code,null,null,ct);return Build([new("GPA tích lũy",gpa.Gpa,"insights",gpa.Classification,"primary"),new("Tín chỉ tích lũy",gpa.PassedCredits,"workspace_premium","/ 130 tín chỉ","success"),new("Môn đã đạt",grades.Count(x=>x.Passed),"task_alt","Kết quả công bố","success"),new("Môn chưa đạt",grades.Count(x=>!x.Passed),"warning","Cần cải thiện","danger")]);}
 private static DashboardDto Build(IReadOnlyCollection<DashboardCardDto> cards)=>new(cards,[new("A",12),new("B+",18),new("B",25),new("C",15),new("D",7),new("F",3)],[new("Công bố bảng điểm","Lớp NOSQL01-01 đã được công bố","5 phút trước","publish"),new("Cập nhật cấu trúc điểm","Phiên bản năm học 2025-2026","1 giờ trước","rule"),new("Đăng nhập hệ thống","Phiên đăng nhập được xác thực","Hôm nay","login")],[new("Bảng điểm chưa hoàn tất","Còn dữ liệu điểm cần kiểm tra","warning"),new("Dữ liệu đã sao lưu","Bản sao lưu gần nhất thành công","success")]);}
